components.css:
.ds-primary {
  background: var(--accent);
  border: 1px solid var(--accent);
  color: white;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  font-weight: 550;
  font-size: 16px;
  padding: 14px 20px;
  min-height: 58px;
  transition:
    background 0.18s ease-out,
    border-color 0.18s ease-out;
}
.ds-primary:hover:not(:disabled) {
  background: #2d432d;
  border-color: #2d432d;
}
.ds-primary:disabled {
  background: #dedfd9;
  border-color: #dedfd9;
  color: var(--muted);
}
.ds-generate {
  width: 100%;
}
.ds-generate > svg:last-child {
  margin-left: auto;
}.ds-primary{font-family:var(--font-body),sans-serif;}.ds-primary:focus-visible{outline:3px solid var(--focus);outline-offset:5px}

.ds-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 10px 14px;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 500;
  color: var(--ink);
  background: transparent;
  border: 1px solid #879481;
  border-radius: 7px;
}
.ds-secondary:hover:not(:disabled) {
  background: #e9eee5;
  border-color: var(--accent);
}
.ds-secondary:disabled {
  color: var(--muted);
  cursor: not-allowed;
}.ds-secondary{font-family:var(--font-body),sans-serif;}.ds-secondary:focus-visible{outline:3px solid var(--focus);outline-offset:5px}

.ds-country-row {
  display: flex;
  align-items: center;
  border: 1px solid #879481;
  border-radius: 6px;
  background: white;
}
.ds-select-wrap {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  min-width: 0;
}
.ds-select-chevron {
  position: absolute;
  right: 14px;
  pointer-events: none;
  color: var(--ink);
}
.ds-select {
  font: inherit;
  -webkit-tap-highlight-color: transparent;
  appearance: none;
  width: 100%;
  min-width: 0;
  padding: 13px 38px 13px 14px;
  border: 0;
  background: transparent;
  border-radius: 6px;
  color: var(--ink);
  font-size: 16px;
}.ds-select{font-family:var(--font-body),sans-serif;}.ds-select:focus-visible{outline:3px solid var(--focus);outline-offset:5px}

.ds-nav {
  height: 100px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}
.ds-nav::after {
  content: "";
  position: absolute;
  inset: auto 36px 0;
  height: 1px;
  background: var(--line);
}
.ds-brand {
  display: inline-flex;
  align-items: center;
  font-size: 23px;
  font-weight: 500;
  letter-spacing: -0.02em;
  white-space: nowrap;
}
.ds-nav a:hover {
  text-decoration: underline;
  text-underline-offset: 5px;
}.ds-nav{font-family:var(--font-body),sans-serif;padding-inline:36px;color:var(--ink);background:var(--paper)}.ds-brand:focus-visible{outline:3px solid var(--focus);outline-offset:5px}

.ds-error {
  display: flex;
  gap: 12px;
  padding: 20px;
  background: #fff0e9;
  border: 1px solid #e4bba8;
  border-radius: 8px;
  font-size: 13px;
  line-height: 1.6;
  color: #923b26;
}
.ds-error > svg {
  flex-shrink: 0;
  margin-top: 3px;
}
.ds-error strong {
  font-weight: 600;
}
.ds-error p {
  margin: 4px 0 0;
}.ds-error{font-family:var(--font-body),sans-serif;}.ds-error:focus-visible{outline:3px solid var(--focus);outline-offset:5px}

.ds-guide {
  margin: 0;
  color: #625370;
  text-align: center;
}

.ds-label {
  display: block;
  margin-bottom: 10px;
  font-size: 12px;
}

.ds-window {
  position: relative;
  width: 140px;
  height: 176px;
  overflow: hidden;
  border-radius: 8px;
  background: #f5f2f9;
}

.ds-corner {
  position: absolute;
  z-index: 1;
  width: 13px;
  height: 13px;
  border-style: solid;
  border-color: #877497;
}

.ds-topLeft {
  top: 10px;
  left: 10px;
  border-width: 1px 0 0 1px;
}

.ds-topRight {
  top: 10px;
  right: 10px;
  border-width: 1px 1px 0 0;
}

.ds-bottomLeft {
  bottom: 10px;
  left: 10px;
  border-width: 0 0 1px 1px;
}

.ds-bottomRight {
  bottom: 10px;
  right: 10px;
  border-width: 0 1px 1px 0;
}

.ds-headroom {
  position: absolute;
  top: 32px;
  right: 20px;
  left: 20px;
  border-top: 1px dashed #b9a9c5;
}

.ds-centerline {
  position: absolute;
  z-index: 1;
  top: 14px;
  bottom: 14px;
  left: 50%;
  border-left: 1px dashed #b9a9c5;
}

.ds-person {
  position: absolute;
  bottom: -12px;
  left: 50%;
  width: 151px;
  height: 165px;
  transform: translateX(-50%);
  color: #9d8cab;
  fill: #e0d6e9;
}

.ds-caption {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 10px;
  font-size: 12px;
  line-height: 1.5;
}

.ds-caption svg {
  flex-shrink: 0;
}.ds-guide{font-family:var(--font-body),sans-serif;}
